import hashlib, subprocess, shutil, os
LEAN = 'def gate (n r : Nat) (p q : Nat → Prop) (h : Nat) : Prop :=\n  ∀ g, g < h → g < n ∨ (p g ∧ (q g ∨ ¬ ∀ j, j + r ≤ g → q j))\ndef blend (S : Nat → Prop) (a b : Nat → Prop) (h : Nat) : Prop :=\n  (S h ∧ a h) ∨ (¬ S h ∧ b h)\ndef eventual (p : Nat → Prop) : Prop := ∃ H, ∀ h, H ≤ h → p h\ndef dbtrace (n k : Nat) (S : Nat → Prop) (h : Nat) : Prop :=\n  (S h ∧ h < k) ∨ (¬ S h ∧ h ≤ n)\ndef selfeq (n r k : Nat) (S d x : Nat → Prop) : Prop :=\n  ∀ h, x h ↔ blend S (fun h => ∀ g, g + k ≤ h → x g) (gate n r x d) h\n\ntheorem hole_window (r t : Nat) (d : Nat → Prop)\n    (pre : ∀ j, j < t → d j) (hole : ¬ d t) (g : Nat) :\n    (d g ∨ ¬ ∀ j, j + r ≤ g → d j) ↔ (d g ∨ t + r ≤ g) := by\n  classical\n  constructor\n  · intro H\n    rcases H with hd | hd\n    · exact Or.inl hd\n    · right\n      by_cases ht : t + r ≤ g\n      · exact ht\n      · exact False.elim (hd (fun j hj => pre j (by omega)))\n  · intro H\n    rcases H with hd | ht\n    · exact Or.inl hd\n    · exact Or.inr (fun H => hole (H t ht))\n\ntheorem least_failure (d : Nat → Prop) (b : Nat) (hb : ¬ d b) :\n    ∃ t, t ≤ b ∧ ¬ d t ∧ ∀ j, j < t → d j := by\n  classical\n  induction b using Nat.strongRecOn with\n  | ind b ih =>\n    by_cases H : ∀ j, j < b → d j\n    · exact ⟨b, Nat.le_refl b, hb, H⟩\n    · obtain ⟨j, hj⟩ := Classical.not_forall.mp H\n      have hjb : j < b := Classical.byContradiction (fun hh => hj (fun h => False.elim (hh h)))\n      have hjd : ¬ d j := fun hd => hj (fun _ => hd)\n      obtain ⟨t, ht, hdt, hp⟩ := ih j hjb hjd\n      exact ⟨t, by omega, hdt, hp⟩\n\ndef dd (n : Nat) (S : Nat → Prop) (h : Nat) := ¬ S h ∧ h ≤ n\ndef cd (n : Nat) (S : Nat → Prop) (h : Nat) := S h ∨ h ≤ n\n\ntheorem db_self (n r : Nat) (hr : 1 ≤ r) (S x : Nat → Prop)\n    (eqn : ∀ h, x h ↔ ¬ S h ∧ gate n r x (dd n S) h) :\n    eventual x ↔ (∃ s, S s ∧ s+r ≤ n+1) ∧ ∀ s, S s → s < n := by\n  classical\n  constructor\n  · intro ⟨H,hH⟩\n    have bound : ∀ s, S s → s < n := by\n      intro s ss\n      by_cases sn : s < n\n      · exact sn\n      · rcases ((eqn (H+s+1)).1 (hH _ (by omega))).2 s (by omega) with small | hh\n        · omega\n        · exact False.elim ((eqn s).1 hh.1 |>.1 ss)\n    refine ⟨?_,bound⟩\n    have gh := ((eqn (H+n+2)).1 (hH _ (by omega))).2 (n+1) (by omega)\n    rcases gh with small | ⟨_,dq⟩\n    · omega\n    · rcases dq with d | nd\n      · have := d.2; omega\n      · apply Classical.byContradiction\n        intro no\n        apply nd\n        intro s hs\n        refine ⟨?_,by omega⟩\n        intro ss\n        exact no ⟨s,ss,hs⟩\n  · intro ⟨⟨s,ss,sr⟩,bound⟩\n    refine ⟨n,?_⟩\n    intro h\n    induction h using Nat.strongRecOn with\n    | ind h ih =>\n      intro nh\n      apply (eqn h).2\n      refine ⟨(fun sh => by have := bound h sh; omega),?_⟩\n      intro g gh\n      by_cases gn : g < n\n      · exact Or.inl gn\n      · refine Or.inr ⟨ih g gh (by omega),?_⟩\n        by_cases ge : g = n\n        · left; subst g; exact ⟨(fun sn => by have := bound n sn; omega),by omega⟩\n        · right; intro all; exact (all s (by omega)).1 ss\n\ntheorem cb_self (n r : Nat) (hr : 1 ≤ r) (S x : Nat → Prop)\n    (eqn : ∀ h, x h ↔ S h ∨ (¬ S h ∧ gate n r x (cd n S) h)) :\n    eventual x ↔ eventual S := by\n  classical\n  constructor\n  · intro hx\n    by_cases es : eventual S\n    · exact es\n    · have missing : ∃ b, n+1 ≤ b ∧ ¬ S b := by\n        apply Classical.byContradiction\n        intro no\n        apply es\n        refine ⟨n+1, ?_⟩\n        intro b hb\n        exact Classical.byContradiction (fun ns => no ⟨b,hb,ns⟩)\n      obtain ⟨b,hb,ns⟩ := missing\n      have holeb : ¬ cd n S b := by intro hd; rcases hd with hs | hn; exact ns hs; omega\n      obtain ⟨t,tb,hole,pre⟩ := least_failure (cd n S) b holeb\n      have tn : n < t := by\n        apply Classical.byContradiction\n        intro no\n        exact hole (Or.inr (by omega))\n      obtain ⟨H,hH⟩ := hx\n      refine ⟨H+t+1, ?_⟩\n      intro h hh\n      rcases (eqn h).1 (hH h (by omega)) with sh | ⟨_,hw⟩\n      · exact sh\n      · rcases hw t (by omega) with small | rest\n        · omega\n        · rcases (hole_window r t _ pre hole t).1 rest.2 with hd | ht\n          · exact False.elim (hole hd)\n          · omega\n  · intro ⟨H,hH⟩\n    exact ⟨H, fun h hh => (eqn h).2 (Or.inl (hH h hh))⟩\n\ntheorem traces (n r : Nat) (S : Nat → Prop) (h : Nat) :\n    (blend S (fun _ => False) (gate n r (fun _ => False) (fun _ => False)) h ↔ dd n S h) ∧\n    (blend S (fun _ => True) (gate n r (fun _ => False) (fun _ => False)) h ↔ cd n S h) := by\n  have hw : gate n r (fun _ => False) (fun _ => False) h ↔ h ≤ n := by\n    constructor\n    · intro H\n      apply Classical.byContradiction\n      intro hn\n      rcases H n (by omega) with small | rest\n      · omega\n      · exact rest.1\n    · intro hn g gh; exact Or.inl (by omega)\n  unfold blend dd cd\n  rw [hw]\n  simp only [and_false, false_or, and_true]\n  constructor\n  · trivial\n  · constructor\n    · intro hh; rcases hh with sh | hh; exact Or.inl sh; exact Or.inr hh.2\n    · intro hh\n      by_cases sh : S h\n      · exact Or.inl sh\n      · rcases hh with hs | hn; exact False.elim (sh hs); exact Or.inr ⟨sh,hn⟩\ntheorem db_safe (n r : Nat) (S p q x : Nat → Prop)\n (eqn : ∀ h, x h ↔ ¬ S h ∧ gate n r p q h)\n (pd : eventual (fun h => ¬ p h)) : eventual (fun h => ¬ x h) := by\n obtain ⟨H,hH⟩ := pd\n refine ⟨H+n+1,fun h hh xh => ?_⟩\n rcases ((eqn h).1 xh).2 (H+n) (by omega) with small | rest\n · omega\n · exact hH (H+n) (by omega) rest.1\n\ntheorem cb_finite_safe (n r M : Nat) (S p q x : Nat → Prop)\n (fin : ∀ h, M ≤ h → ¬ S h)\n (eqn : ∀ h, x h ↔ S h ∨ (¬ S h ∧ gate n r p q h))\n (pd : eventual (fun h => ¬ p h)) : eventual (fun h => ¬ x h) := by\n obtain ⟨H,hH⟩ := pd\n refine ⟨M+H+n+1,fun h hh xh => ?_⟩\n rcases (eqn h).1 xh with sh | gh\n · exact fin h (by omega) sh\n · rcases gh.2 (H+n) (by omega) with small | rest\n   · omega\n   · exact hH (H+n) (by omega) rest.1\n\ntheorem cb_cofinite_exploited (n r : Nat) (S x : Nat → Prop)\n (cofin : eventual S)\n (eqn : ∀ h, x h ↔ S h ∨ (¬ S h ∧ gate n r (fun _ => False) (fun _ => False) h)) : eventual x := by\n obtain ⟨H,hH⟩ := cofin\n exact ⟨H,fun h hh => (eqn h).2 (Or.inl (hH h hh))⟩\n#print axioms db_self\n#print axioms cb_self\n#print axioms traces\n#print axioms db_safe\n#print axioms cb_finite_safe\n#print axioms cb_cofinite_exploited\n'
assert hashlib.sha256(LEAN.encode()).hexdigest() == '3749d2a739e3da9a7182127a5eb131164ad0c1bcdeeb1385242b8cff37d909d4'
binary = next((p for p in (shutil.which('lean'), '/opt/elan/bin/lean', os.path.expanduser('~/.elan/bin/lean')) if p and os.path.exists(p)), None)
assert binary, 'Lean missing'
r = subprocess.run([binary, '--stdin'], input=LEAN, text=True, capture_output=True, timeout=90)
assert r.returncode == 0, r.stdout+r.stderr
assert 'sorryAx' not in r.stdout and r.stdout.count('axioms') == 6
for old,new in [('s+r ≤ n+1)', 's+r ≤ n+2)'), ('s < n := by', 's ≤ n := by'), ('eventual x ↔ eventual S', 'eventual x ↔ eventual (fun h => ¬ S h)')]:
    bad=LEAN.replace(old,new)
    assert bad != LEAN
    r=subprocess.run([binary,'--stdin'],input=bad,text=True,capture_output=True,timeout=15)
    assert r.returncode != 0, 'negative control accepted'
print('PASS: six Lean theorems, three mutations rejected')
